        result = subprocess.run(['bash', script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    except Exception as e:
        raise RuntimeError(f"Error executing script: {e}")
    end_time = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    exit_status = result.returncode
    if result.returncode != 0:
        raise RuntimeError(f"Script exited with status {result.returncode}: {result.stderr.decode('utf-8', errors='ignore')}")
    log_entry = {
        'start_time': start_time,
        'end_time': end_time,
        'exit_status': exit_status
    }
    try:
        if os.path.exists(log_file):
            with open(log_file, 'r') as f:
                try:
                    data = json.load(f)
                except json.JSONDecodeError:
                    data = []
        else:
            data = []
        if isinstance(data, list):
            data.append(log_entry)
        else:
            data = [data, log_entry]
        with open(log_file, 'w') as f:
            json.dump(data, f)
    except Exception:
        pass
    return log_entry
