import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not isinstance(script_path, str):
        raise TypeError("script_path must be a string")
    if not os.path.exists(script_path) or not os.path.isfile(script_path):
        raise OSError("Script path does not exist or is not a file")
    start_time = time.time()
    process = subprocess.Popen(["bash", script_path])
    ps_proc = psutil.Process(process.pid)
    cpu_accum = 0.0
    mem_accum = 0
    last_cpu_times = None
    interval = 0.1
    try:
        while True:
            if time.time() - start_time > timeout:
                process.terminate()
                try:
                    process.wait(timeout=5)
                except Exception:
                    process.kill()
                break
            try:
                if ps_proc.status() == psutil.STATUS_ZOMBIE:
                    break
            except psutil.NoSuchProcess:
                break
            try:
                cpu_times = ps_proc.cpu_times()
                if last_cpu_times is not None:
                    delta_user = cpu_times.user - last_cpu_times.user
                    delta_system = cpu_times.system - last_cpu_times.system
                    delta_cpu = max(delta_user + delta_system, 0.0)
                    cpu_accum += delta_cpu * 100.0
                last_cpu_times = cpu_times
            except psutil.NoSuchProcess:
                break
            try:
                mem_info = ps_proc.memory_info()
                mem_accum += max(mem_info.rss, 0)
            except psutil.NoSuchProcess:
                break
            if process.poll() is not None:
                break
            time.sleep(interval)
    finally:
        if process.poll() is None:
            try:
                process.terminate()
                process.wait(timeout=5)
            except Exception:
                try:
                    process.kill()
                except Exception:
                    pass
    return {"CPU Usage": cpu_accum, "Memory Usage": mem_accum}
